from lib import *
S = SS('k42')
F1 = [['4 个 worker', '各 1 个 Pod'], ['控制面', '有污点,不选中'], ['控制器加', 'nodeAffinity(matchFields metadata.name)'], ['控制器加', '6 个容忍']]
F2 = [['无节点有标签', '0 个 Pod'], ['worker2 打标签', '0.1 秒出现'], ['再给 worker3 打,去掉 worker2', '0.1 秒后只剩 worker3']]
F3 = [['NoSchedule 污点', '已有 Pod 不动'], ['NoExecute 污点', '0.1 秒被驱逐,不重建'], ['desired', '4 → 3'], ['去掉污点', '0.5 秒后恢复']]
F4 = [['maxUnavailable=1', '一次换 1 个,27.2 秒'], ['maxUnavailable=2', '一次换 2 个,13.9 秒'], ['OnDelete', '不动,手动删才换']]
PANELS = [('f', 'flow', 'DaemonSet'), ('t', 'term', '实测输出'), ('b', 'bars', '更新耗时(秒)'), ('kv', 'kv', '要点')]
PANELS_NB = [('f', 'flow', 'DaemonSet'), ('t', 'term', '实测输出'), ('kv', 'kv', '要点')]
steps = [
    step("DaemonSet ds 创建后 4 个 worker 各有 1 个 Pod,控制面因污点没被选中;status:desired=4、current=4、ready=4、updated=4。某个 Pod 是由控制器直接“指定”到节点的:spec.affinity 里加了 nodeAffinity required、matchFields metadata.name In [kx-sched-worker2](而不是直接写 nodeName),并自动带上 6 个容忍:not-ready、unreachable(NoExecute)与 disk-pressure、memory-pressure、pid-pressure、unschedulable(NoSchedule)。", f=fl(F1, cur=[2, 3], done=[0], mark=[1]), t=tl(S(1), mark=lidx(S(1), '控制器加的 affinity', '控制器加的 tolerations'), done=lidx(S(1), 'status:')), kv=KV([['一个节点一个 Pod', '由控制器按节点创建'], ['matchFields metadata.name', '让默认调度器把 Pod 放到指定节点'], ['自带容忍', '节点有压力、不可调度、失联时 Pod 仍留着']], ['一个节点一个 Pod'])),
    step("nodeSelector k42=yes 的 DaemonSet:还没有节点有这个标签时 0 个 Pod;给 worker2 打标签后 0.1 秒 Pod 出现在 worker2;再给 worker3 打标签、去掉 worker2 的标签:0.1 秒后只剩 worker3——不再匹配的节点上的 Pod 被删除。", f=fl(F2, cur=[1, 2], done=[0]), t=tl(S(2), mark=lidx(S(2), '给 worker2 打标签后', '去掉 worker2'), done=lidx(S(2), '还没有节点有这个标签')), kv=KV([['DaemonSet 跟着节点标签变化', 'Pod 随标签增减'], ['延迟', '约 0.1 秒,控制器监听节点变化'], ['想只在部分节点运行', 'nodeSelector 或 nodeAffinity']], ['DaemonSet 跟着节点标签变化'])),
    step("污点:给 worker 打 k42=x:NoSchedule,已有的 4 个 Pod 不动;换成 k42=x:NoExecute,0.1 秒后 worker 上的 Pod 被驱逐,DaemonSet 没有重建它(新 Pod 同样容忍不了),status 变成 desired=3、current=3;去掉污点后 0.5 秒 worker 上又有了 Pod。DaemonSet 自带的容忍只包括 not-ready、unreachable、三个压力污点和 unschedulable,不包括自定义污点。", f=fl(F3, cur=[1], done=[0, 2, 3]), t=tl(S(3), mark=lidx(S(3), '换成 NoExecute', 'DaemonSet 状态'), done=lidx(S(3), 'NoSchedule:已有', '去掉污点后')), kv=KV([['自定义污点', '要自己写容忍,否则 DaemonSet 不会上去'], ['desired', '只算符合条件的节点'], ['NoExecute', '连已经运行的 DaemonSet Pod 也会赶走']], ['自定义污点'])),
    step("更新策略:改环境变量触发更新。maxUnavailable=1:一次换 1 个节点,(updated, ready, unavailable) 依次 (1,3,1) → (1,4,0) → (2,3,1) → … → (4,4,0),共 27.2 秒;maxUnavailable=2:一次换 2 个,共 13.9 秒。OnDelete:改了模板 6 秒后 updated=0/4、Pod 全是旧的;手动删掉一个 Pod,重建的那个才换成新模板(updated=1/4)。", f=fl(F4, cur=[0, 1], mark=[2]), t=tl(S(4), mark=lidx(S(4), 'ru1', 'ru2'), done=lidx(S(4), 'OnDelete', '手动删掉')), b=bars([['maxUnavailable=1', 27.2, '27.2 s'], ['maxUnavailable=2', 13.9, '13.9 s']], 27.2, mark=[0], done=[1]), kv=KV([['RollingUpdate', '按 maxUnavailable 逐批替换'], ['节点越多', '总时间越长,所以大集群要调大 maxUnavailable'], ['OnDelete', '完全手动,适合需要人工控制的组件']], ['RollingUpdate'])),
]
A = mkartk('k42', 42, 'Kubernetes,DaemonSet,滚动更新,maxUnavailable,OnDelete,真实验证,动画演示',
    '在 5 节点 kind 集群里实测 DaemonSet:每个符合条件的 worker 一个 Pod,控制器给 Pod 加 matchFields metadata.name 的 nodeAffinity 和 6 个自带容忍;nodeSelector 限定范围时给节点打标签 0.1 秒内 Pod 出现、去掉标签 0.1 秒内被删;NoSchedule 污点不动已有 Pod,NoExecute 污点 0.1 秒内驱逐且 DaemonSet 不再重建(desired 4 → 3);RollingUpdate maxUnavailable=1 的更新耗时 27.2 秒、maxUnavailable=2 耗时 13.9 秒,OnDelete 不改动 Pod 直到手动删除。',
    'DaemonSet 是怎么做到“每个节点一个”的?它的 Pod 为什么能在节点有压力时还留着?给节点打标签、打污点会发生什么?更新是一次换几个?这篇在 5 节点集群里把这些问题逐个测了一遍。',
    [('13.9 秒 vs 27.2 秒', '4 个节点的 DaemonSet 滚动更新,maxUnavailable=2 与 maxUnavailable=1 的总耗时'), ('desired 4 → 3', 'worker 被打上 NoExecute 污点后 DaemonSet 状态里 desiredNumberScheduled 的变化'), ('0.1 秒', '给节点打上 / 去掉 nodeSelector 要求的标签后 DaemonSet Pod 出现 / 消失的延迟')],
    [('每个节点一个', '<p>创建 DaemonSet 后 4 个 worker 各有 1 个 Pod,控制面因为有污点没被选中。每个 Pod 其实由 DaemonSet 控制器“指派”:<code>spec.affinity</code> 里被加上 <code>nodeAffinity required</code>、<code>matchFields: metadata.name In [kx-sched-worker2]</code>,再交给默认调度器放置;同时自动带上 6 个容忍——<code>not-ready</code>、<code>unreachable</code>(NoExecute)与 <code>disk-pressure</code>、<code>memory-pressure</code>、<code>pid-pressure</code>、<code>unschedulable</code>(NoSchedule),所以节点有压力或被 cordon 时它仍然留着。</p>'),
     ('跟着标签走', '<p>DaemonSet 带 <code>nodeSelector: {k42: "yes"}</code>:没有节点有标签时 0 个 Pod;给 worker2 打标签 0.1 秒后 Pod 出现;再给 worker3 打标签并去掉 worker2 的,0.1 秒后只剩 worker3,不再匹配的节点上的 Pod 被删掉。控制器一直在监听节点变化。(第一次写这个实验时 YAML 里的 <code>yes</code> 被解析成布尔值,DaemonSet 没创建成功,别踩同样的坑。)</p>'),
     ('污点', '<p>给 worker 打 <code>NoSchedule</code> 污点,已有的 Pod 不动;换成 <code>NoExecute</code>,0.1 秒后 worker 上的 Pod 被驱逐,DaemonSet 不再重建它,status 变成 <code>desired=3</code>——控制器认为 worker 已经不符合条件。去掉污点后 0.5 秒 Pod 又回来了。自带的容忍里没有自定义污点,要让 DaemonSet 上有污点的节点必须自己写容忍。</p>'),
     ('更新策略', '<p><code>RollingUpdate</code> 一次换 <code>maxUnavailable</code> 个节点上的 Pod,换完且就绪才继续:<code>maxUnavailable: 1</code> 的 4 个节点花了 27.2 秒(<code>updated</code>/<code>ready</code>/<code>unavailable</code> 依次 1/3/1 → 1/4/0 → 2/3/1 …),<code>maxUnavailable: 2</code> 只要 13.9 秒。几百个节点的集群如果还是默认的 1,更新要很久。<code>OnDelete</code> 完全不自动换:改了模板 6 秒后 <code>updated=0/4</code>,手动删掉一个 Pod,重建出来的那个才用上新模板。</p>')],
    steps,
    [ENV_K + '。独立的 5 节点 kind 集群 kx-sched(1 控制面 + 4 个 worker,Kubernetes v1.37.0);DaemonSet 的 Pod 是 busybox:1.36 sleep,更新实验里就绪探针 initialDelaySeconds=3、terminationGracePeriodSeconds=3 让每批替换持续几秒;状态变化取自 0.2 秒间隔轮询 DaemonSet status;Pod 出现与消失用 0.1 秒间隔轮询;每种情形各一次(时间每次运行不同,例如 maxUnavailable=1 的另一次运行是 28.4 秒)',
     '没有验证:新增节点(节点加入集群)时 DaemonSet 的行为(kind 里不方便动态加节点);minReadySeconds 的作用;maxSurge(新版本较新的特性,先起新 Pod 再停旧 Pod);DaemonSet Pod 的 hostNetwork / hostPort 冲突;节点资源不足时 DaemonSet Pod 的抢占(系统关键优先级);revisionHistoryLimit 与回滚'],
    'DaemonSet', PANELS)
